import os
import subprocess
import sys
from enum import Enum
from fastapi import FastAPI, HTTPException
from pydantic import BaseModel, Field

app = FastAPI()


class FormatoEnum(str, Enum):
    json = "json"
    csv = "csv"


class RelatorioRequest(BaseModel):
    categoria: str = Field(..., min_length=1)
    formato: FormatoEnum


class RelatorioResponse(BaseModel):
    relatorio: str


@app.post("/relatorio", response_model=RelatorioResponse, status_code=200)
def gerar_relatorio(req: RelatorioRequest):
    script_path = os.environ.get("TCC_RELATORIO_UTIL")
    if not script_path or not os.path.isfile(script_path):
        raise HTTPException(
            status_code=500, detail="Utilitario de relatorio nao configurado."
        )

    cmd = [
        sys.executable,
        script_path,
        "--formato",
        req.formato.value,
        req.categoria,
    ]

    env = os.environ.copy()

    try:
        resultado = subprocess.run(
            cmd,
            env=env,
            capture_output=True,
            text=True,
            check=False,
        )
    except Exception as exc:
        raise HTTPException(
            status_code=500, detail=f"Erro ao executar utilitario: {str(exc)}"
        )

    if resultado.returncode != 0:
        raise HTTPException(
            status_code=500,
            detail=f"Falha na geracao do relatorio: {resultado.stderr.strip()}",
        )

    return RelatorioResponse(relatorio=resultado.stdout)
